function App() {
  const [open, setOpen] = React.useState(false);
  const trigger = React.useRef(null);
  const first = React.useRef(null);
  React.useEffect(() => {
    if (open) first.current?.focus();
  }, [open]);
  function close() {
    setOpen(false);
    trigger.current?.focus();
  }
  return <nav onKeyDown={event => {
    if (event.key === 'Escape') close();
  }}>
    <button ref={trigger} aria-expanded={open}
      aria-controls="help-panel"
      onClick={() => setOpen(value => !value)}>Help</button>
    {open && <ul id="help-panel">
      <li><button ref={first}>Read instructions</button></li>
      <li><button>Contact details</button></li>
    </ul>}
  </nav>;
}

