function App() {
  const [status, setStatus] = React.useState('idle');
  const [books, setBooks] = React.useState([]);
  const [error, setError] = React.useState('');
  const latest = React.useRef(0);
  function load(mode) {
    const id = ++latest.current;
    setStatus('loading');
    setError('');
    setTimeout(() => {
      if (id !== latest.current) return;
      if (mode === 'error') {
        setError('Could not load the library.');
        setStatus('error');
        return;
      }
      setBooks(mode === 'empty' ? [] : ['Forest Guide']);
      setStatus('success');
    }, mode === 'slow' ? 120 : 20);
  }
  return <main>
    <button onClick={() => load('slow')}>Slow sample</button>
    <button onClick={() => load('error')}>Error sample</button>
    <button onClick={() => load('empty')}>Empty sample</button>
    {status === 'loading' && <p>Loading…</p>}
    {status === 'error' && <p role="alert">{error}</p>}
    {status === 'success' && books.length === 0 && <p>No books.</p>}
    {status === 'success' && <ul>
      {books.map(book => <li key={book}>{book}</li>)}
    </ul>}
  </main>;
}

const items = ['Cedar', 'Maple', 'Cedar guide', 'Oak'];
function measure(query) {
  let examined = 0;
  const matches = items.filter(item => {
    examined += 1;
    return item.toLowerCase().includes(query.toLowerCase());
  });
  return { matches, examined };
}
console.log(measure('cedar'));

function App() {
  const items = React.useMemo(() => ['Cedar', 'Maple', 'Cedar guide'], []);
  const [query, setQuery] = React.useState('cedar');
  const [repeat, setRepeat] = React.useState(0);
  function measure() {
    let examined = 0;
    const matches = items.filter(item => {
      examined += 1;
      return item.toLowerCase().includes(query.toLowerCase());
    });
    return { matches, examined };
  }
  const baseline = React.useMemo(measure, [items, query, repeat]);
  const cached = React.useMemo(measure, [items, query]);
  return <main>
    <label>Search <input value={query}
      onChange={e => setQuery(e.target.value)} /></label>
    <button onClick={() => setRepeat(value => value + 1)}>Repeat</button>
    <p>Matches: {cached.matches.length}</p>
    <p>Same count: {baseline.matches.length === cached.matches.length ? 'yes' : 'no'}</p>
  </main>;
}

